test('lateFee calculation is accurate', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-01',
    lines: [{ sku: 'DES-HOUR', qty: 100, discountPercent: 0 }],
    terms: 'NET30',
  });
  const issued = issueInvoice(inv.value, []);
  const { total } = invoiceTotals(issued.value);

  const asOf = '2024-02-20';
  const fee = lateFee(issued.value, asOf);
  const daysOverdue = 20;
  const expected = Math.round((total * 0.04 / 100) * daysOverdue);
  assert.equal(fee, expected);
});

