      customerId: `C-${i.toString().padStart(3, '0')}`,
      issueDate: '2024-01-15',
      lines: [{ sku: 'DES-HOUR', qty: i * 10, discountPercent: 0 }],
    });
    const issued = issueInvoice(inv.value, invoices.map((inv) => inv.number));
    invoices.push(issued.value);
