  });
  let issued = issueInvoice(inv.value, []);
  const { total } = invoiceTotals(issued.value);
  const partiallyPaid = recordPayment(issued.value, { amount: Math.floor(total / 2), date: '2024-02-15' }).value;

  const invoices = [partiallyPaid];
